"""Model implementations for SCAM benchmark."""

from scam.models.base import BaseModel
from scam.utils.config import resolve_model_provider

__all__ = [
    "BaseModel",
    "AnthropicModel",
    "OpenAIModel",
    "GeminiModel",
    "create_model",
]


def create_model(model_name: str) -> BaseModel:
    """Create a model instance based on the model name.

    Provider adapters are imported lazily so that importing this package (or the
    runner, which depends on ``scam.models.base``) does not require every
    provider SDK to be installed — only the SDK for the selected provider.
    """
    provider = resolve_model_provider(model_name)
    if provider == "anthropic":
        from scam.models.anthropic import AnthropicModel

        return AnthropicModel(model_name)
    elif provider == "openai":
        from scam.models.openai import OpenAIModel

        return OpenAIModel(model_name)
    elif provider == "google":
        from scam.models.gemini import GeminiModel

        return GeminiModel(model_name)
    else:
        raise ValueError(f"Unknown model provider for: {model_name}")


def __getattr__(name: str):
    """Lazily expose provider adapter classes (PEP 562).

    Keeps ``from scam.models import AnthropicModel`` working without importing
    each provider SDK at package load time.
    """
    if name == "AnthropicModel":
        from scam.models.anthropic import AnthropicModel

        return AnthropicModel
    if name == "OpenAIModel":
        from scam.models.openai import OpenAIModel

        return OpenAIModel
    if name == "GeminiModel":
        from scam.models.gemini import GeminiModel

        return GeminiModel
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")
